bool AssistantMediaDataSourceStubDispatch::Accept(
    AssistantMediaDataSource* impl,
    mojo::Message* message) {
  switch (message->header()->name) {
    case internal::kAssistantMediaDataSource_Read_Name: {
      break;
    }
  }
  return false;
}

// static
bool AssistantMediaDataSourceStubDispatch::AcceptWithResponder(
    AssistantMediaDataSource* impl,
    mojo::Message* message,
    std::unique_ptr<mojo::MessageReceiverWithStatus> responder) {
  [[maybe_unused]] const bool message_is_sync =
      message->has_flag(mojo::Message::kFlagIsSync);
  [[maybe_unused]] const uint64_t request_id = message->request_id();
  switch (message->header()->name) {
    case internal::kAssistantMediaDataSource_Read_Name: {

      internal::AssistantMediaDataSource_Read_Params_Data* params =
          reinterpret_cast<
              internal::AssistantMediaDataSource_Read_Params_Data*>(
                  message->mutable_payload());
      
      
      // Validation for AssistantMediaDataSource.0
      bool success = true;
      uint32_t p_size{};
      AssistantMediaDataSource_Read_ParamsDataView input_data_view(params, message);
      
      if (success)
        p_size = input_data_view.size();
      if (!success) {
        ReportValidationErrorForMessage(
            message,
            mojo::internal::VALIDATION_ERROR_DESERIALIZATION_FAILED,
            AssistantMediaDataSource::Name_, 0, false);
        return false;
      }
      AssistantMediaDataSource::ReadCallback callback =
          AssistantMediaDataSource_Read_ProxyToResponder::CreateCallback(
              *message, std::move(responder));
      // A null |impl| means no implementation was bound.
      DCHECK(impl);
      impl->Read(        
        std::move(p_size), std::move(callback));
      return true;
    }
  }
  return false;
}
